# -*- coding: utf-8 -*-
# 12-ingilizce-14 görsel modülü

GORSELLER = {'b1': '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Poppins, sans-serif"><rect width="700" height="260" rx="16" fill="#eff6ff" stroke="#2563eb" stroke-width="2"/><text x="350" y="28" text-anchor="middle" font-size="15" font-weight="700" fill="#1e3a8a">Theme 5: Psychology - Vocabulary of Moods and Emotional States</text><rect x="28" y="50" width="305" height="174" rx="12" fill="#ffffff" stroke="#16a34a" stroke-width="2"/><rect x="28" y="50" width="305" height="32" rx="12" fill="#16a34a"/><text x="180" y="71" text-anchor="middle" font-size="12" font-weight="700" fill="#ffffff">Positive and Balanced Moods</text><text x="44" y="102" font-size="11" font-weight="700" fill="#15803d">• Serene / Tranquil:</text><text x="165" y="102" font-size="10.5" fill="#14532d">Sakin, huzurlu, dingin</text><text x="44" y="126" font-size="11" font-weight="700" fill="#15803d">• Cheerful / Elated:</text><text x="165" y="126" font-size="10.5" fill="#14532d">Neşeli, coşkulu, sevinçli</text><text x="44" y="150" font-size="11" font-weight="700" fill="#15803d">• Optimistic / Hopeful:</text><text x="175" y="150" font-size="10.5" fill="#14532d">İyimser, umut dolu</text><text x="44" y="174" font-size="11" font-weight="700" fill="#15803d">• Resilient:</text><text x="120" y="174" font-size="10.5" fill="#14532d">Psikolojik olarak sağlam, dirençli</text><text x="44" y="198" font-size="11" font-weight="700" fill="#15803d">• Empathetic:</text><text x="135" y="198" font-size="10.5" fill="#14532d">Empati kurabilen, anlayışlı</text><rect x="367" y="50" width="305" height="174" rx="12" fill="#ffffff" stroke="#dc2626" stroke-width="2"/><rect x="367" y="50" width="305" height="32" rx="12" fill="#dc2626"/><text x="520" y="71" text-anchor="middle" font-size="12" font-weight="700" fill="#ffffff">Challenging and Stressful Moods</text><text x="383" y="102" font-size="11" font-weight="700" fill="#b91c1c">• Overwhelmed:</text><text x="485" y="102" font-size="10.5" fill="#7f1d1d">Bunalmış, yük altında kalmış</text><text x="383" y="126" font-size="11" font-weight="700" fill="#b91c1c">• Anxious / Apprehensive:</text><text x="538" y="126" font-size="10.5" fill="#7f1d1d">Kaygılı, endişeli</text><text x="383" y="150" font-size="11" font-weight="700" fill="#b91c1c">• Frustrated:</text><text x="468" y="150" font-size="10.5" fill="#7f1d1d">Hayal kırıklığına uğramış, yılgın</text><text x="383" y="174" font-size="11" font-weight="700" fill="#b91c1c">• Exhausted / Burned out:</text><text x="540" y="174" font-size="10.5" fill="#7f1d1d">Bitkin, tükenmiş</text><text x="383" y="198" font-size="11" font-weight="700" fill="#b91c1c">• Gloomy / Melancholic:</text><text x="530" y="198" font-size="10.5" fill="#7f1d1d">Karamsar, hüzünlü</text><text x="350" y="246" text-anchor="middle" font-size="11" font-weight="600" fill="#1e3a8a">Expressing emotions accurately is the first step toward psychological well-being.</text></svg>', '1': '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Poppins, sans-serif"><rect width="700" height="260" rx="16" fill="#eff6ff" stroke="#2563eb" stroke-width="2"/><text x="350" y="28" text-anchor="middle" font-size="15" font-weight="700" fill="#1e3a8a">Theme 5: Psychology - Vocabulary of Moods and Emotional States</text><rect x="28" y="50" width="305" height="174" rx="12" fill="#ffffff" stroke="#16a34a" stroke-width="2"/><rect x="28" y="50" width="305" height="32" rx="12" fill="#16a34a"/><text x="180" y="71" text-anchor="middle" font-size="12" font-weight="700" fill="#ffffff">Positive and Balanced Moods</text><text x="44" y="102" font-size="11" font-weight="700" fill="#15803d">• Serene / Tranquil:</text><text x="165" y="102" font-size="10.5" fill="#14532d">Sakin, huzurlu, dingin</text><text x="44" y="126" font-size="11" font-weight="700" fill="#15803d">• Cheerful / Elated:</text><text x="165" y="126" font-size="10.5" fill="#14532d">Neşeli, coşkulu, sevinçli</text><text x="44" y="150" font-size="11" font-weight="700" fill="#15803d">• Optimistic / Hopeful:</text><text x="175" y="150" font-size="10.5" fill="#14532d">İyimser, umut dolu</text><text x="44" y="174" font-size="11" font-weight="700" fill="#15803d">• Resilient:</text><text x="120" y="174" font-size="10.5" fill="#14532d">Psikolojik olarak sağlam, dirençli</text><text x="44" y="198" font-size="11" font-weight="700" fill="#15803d">• Empathetic:</text><text x="135" y="198" font-size="10.5" fill="#14532d">Empati kurabilen, anlayışlı</text><rect x="367" y="50" width="305" height="174" rx="12" fill="#ffffff" stroke="#dc2626" stroke-width="2"/><rect x="367" y="50" width="305" height="32" rx="12" fill="#dc2626"/><text x="520" y="71" text-anchor="middle" font-size="12" font-weight="700" fill="#ffffff">Challenging and Stressful Moods</text><text x="383" y="102" font-size="11" font-weight="700" fill="#b91c1c">• Overwhelmed:</text><text x="485" y="102" font-size="10.5" fill="#7f1d1d">Bunalmış, yük altında kalmış</text><text x="383" y="126" font-size="11" font-weight="700" fill="#b91c1c">• Anxious / Apprehensive:</text><text x="538" y="126" font-size="10.5" fill="#7f1d1d">Kaygılı, endişeli</text><text x="383" y="150" font-size="11" font-weight="700" fill="#b91c1c">• Frustrated:</text><text x="468" y="150" font-size="10.5" fill="#7f1d1d">Hayal kırıklığına uğramış, yılgın</text><text x="383" y="174" font-size="11" font-weight="700" fill="#b91c1c">• Exhausted / Burned out:</text><text x="540" y="174" font-size="10.5" fill="#7f1d1d">Bitkin, tükenmiş</text><text x="383" y="198" font-size="11" font-weight="700" fill="#b91c1c">• Gloomy / Melancholic:</text><text x="530" y="198" font-size="10.5" fill="#7f1d1d">Karamsar, hüzünlü</text><text x="350" y="246" text-anchor="middle" font-size="11" font-weight="600" fill="#1e3a8a">Expressing emotions accurately is the first step toward psychological well-being.</text></svg>', 'b2': '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Poppins, sans-serif"><rect width="700" height="260" rx="16" fill="#f0fdf4" stroke="#16a34a" stroke-width="2"/><text x="350" y="28" text-anchor="middle" font-size="15" font-weight="700" fill="#14532d">Making Suggestions: Grammar Patterns and Verb Forms</text><rect x="24" y="50" width="205" height="172" rx="12" fill="#ffffff" stroke="#16a34a" stroke-width="2"/><rect x="24" y="50" width="205" height="32" rx="12" fill="#16a34a"/><text x="126" y="71" text-anchor="middle" font-size="11.5" font-weight="700" fill="#ffffff">Pattern 1: + Base Verb (V1)</text><text x="38" y="102" font-size="10.5" font-weight="700" fill="#166534">• Why don t you / we + V1?</text><text x="44" y="118" font-size="9.5" fill="#14532d">Why don t you talk to a counselor?</text><text x="38" y="142" font-size="10.5" font-weight="700" fill="#166534">• You should / ought to + V1</text><text x="44" y="158" font-size="9.5" fill="#14532d">You ought to get enough sleep.</text><text x="38" y="182" font-size="10.5" font-weight="700" fill="#166534">• You had better + V1</text><text x="44" y="198" font-size="9.5" fill="#14532d">You had better slow down now.</text><rect x="247" y="50" width="205" height="172" rx="12" fill="#ffffff" stroke="#0284c7" stroke-width="2"/><rect x="247" y="50" width="205" height="32" rx="12" fill="#0284c7"/><text x="350" y="71" text-anchor="middle" font-size="11.5" font-weight="700" fill="#ffffff">Pattern 2: + Gerund (V-ing)</text><text x="261" y="102" font-size="10.5" font-weight="700" fill="#075985">• How about + V-ing / Noun?</text><text x="267" y="118" font-size="9.5" fill="#0c4a6e">How about practicing mindfulness?</text><text x="261" y="142" font-size="10.5" font-weight="700" fill="#075985">• What about + V-ing / Noun?</text><text x="267" y="158" font-size="9.5" fill="#0c4a6e">What about taking a short walk?</text><text x="261" y="182" font-size="10.5" font-weight="700" fill="#075985">• Have you considered + V-ing?</text><text x="267" y="198" font-size="9.5" fill="#0c4a6e">Have you considered keeping a diary?</text><rect x="470" y="50" width="205" height="172" rx="12" fill="#ffffff" stroke="#7c3aed" stroke-width="2"/><rect x="470" y="50" width="205" height="32" rx="12" fill="#7c3aed"/><text x="572" y="71" text-anchor="middle" font-size="11.5" font-weight="700" fill="#ffffff">Pattern 3: Suggest / If Clause</text><text x="484" y="102" font-size="10.5" font-weight="700" fill="#6b21a8">• suggest / recommend + V-ing</text><text x="490" y="118" font-size="9.5" fill="#4c1d95">I suggest doing breathing exercises.</text><text x="484" y="142" font-size="10.5" font-weight="700" fill="#6b21a8">• suggest + that + S + (should) V1</text><text x="490" y="158" font-size="9.5" fill="#4c1d95">I suggest that he see a specialist.</text><text x="484" y="182" font-size="10.5" font-weight="700" fill="#6b21a8">• If I were you, I would + V1</text><text x="490" y="198" font-size="9.5" fill="#4c1d95">If I were you, I would rest today.</text><text x="350" y="246" text-anchor="middle" font-size="11" font-weight="600" fill="#14532d">Pay attention to whether the structure takes a bare infinitive (V1) or a gerund (V-ing).</text></svg>', '2': '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Poppins, sans-serif"><rect width="700" height="260" rx="16" fill="#f0fdf4" stroke="#16a34a" stroke-width="2"/><text x="350" y="28" text-anchor="middle" font-size="15" font-weight="700" fill="#14532d">Making Suggestions: Grammar Patterns and Verb Forms</text><rect x="24" y="50" width="205" height="172" rx="12" fill="#ffffff" stroke="#16a34a" stroke-width="2"/><rect x="24" y="50" width="205" height="32" rx="12" fill="#16a34a"/><text x="126" y="71" text-anchor="middle" font-size="11.5" font-weight="700" fill="#ffffff">Pattern 1: + Base Verb (V1)</text><text x="38" y="102" font-size="10.5" font-weight="700" fill="#166534">• Why don t you / we + V1?</text><text x="44" y="118" font-size="9.5" fill="#14532d">Why don t you talk to a counselor?</text><text x="38" y="142" font-size="10.5" font-weight="700" fill="#166534">• You should / ought to + V1</text><text x="44" y="158" font-size="9.5" fill="#14532d">You ought to get enough sleep.</text><text x="38" y="182" font-size="10.5" font-weight="700" fill="#166534">• You had better + V1</text><text x="44" y="198" font-size="9.5" fill="#14532d">You had better slow down now.</text><rect x="247" y="50" width="205" height="172" rx="12" fill="#ffffff" stroke="#0284c7" stroke-width="2"/><rect x="247" y="50" width="205" height="32" rx="12" fill="#0284c7"/><text x="350" y="71" text-anchor="middle" font-size="11.5" font-weight="700" fill="#ffffff">Pattern 2: + Gerund (V-ing)</text><text x="261" y="102" font-size="10.5" font-weight="700" fill="#075985">• How about + V-ing / Noun?</text><text x="267" y="118" font-size="9.5" fill="#0c4a6e">How about practicing mindfulness?</text><text x="261" y="142" font-size="10.5" font-weight="700" fill="#075985">• What about + V-ing / Noun?</text><text x="267" y="158" font-size="9.5" fill="#0c4a6e">What about taking a short walk?</text><text x="261" y="182" font-size="10.5" font-weight="700" fill="#075985">• Have you considered + V-ing?</text><text x="267" y="198" font-size="9.5" fill="#0c4a6e">Have you considered keeping a diary?</text><rect x="470" y="50" width="205" height="172" rx="12" fill="#ffffff" stroke="#7c3aed" stroke-width="2"/><rect x="470" y="50" width="205" height="32" rx="12" fill="#7c3aed"/><text x="572" y="71" text-anchor="middle" font-size="11.5" font-weight="700" fill="#ffffff">Pattern 3: Suggest / If Clause</text><text x="484" y="102" font-size="10.5" font-weight="700" fill="#6b21a8">• suggest / recommend + V-ing</text><text x="490" y="118" font-size="9.5" fill="#4c1d95">I suggest doing breathing exercises.</text><text x="484" y="142" font-size="10.5" font-weight="700" fill="#6b21a8">• suggest + that + S + (should) V1</text><text x="490" y="158" font-size="9.5" fill="#4c1d95">I suggest that he see a specialist.</text><text x="484" y="182" font-size="10.5" font-weight="700" fill="#6b21a8">• If I were you, I would + V1</text><text x="490" y="198" font-size="9.5" fill="#4c1d95">If I were you, I would rest today.</text><text x="350" y="246" text-anchor="middle" font-size="11" font-weight="600" fill="#14532d">Pay attention to whether the structure takes a bare infinitive (V1) or a gerund (V-ing).</text></svg>', 'b3': '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Poppins, sans-serif"><rect width="700" height="260" rx="16" fill="#fffbeb" stroke="#d97706" stroke-width="2"/><text x="350" y="28" text-anchor="middle" font-size="15" font-weight="700" fill="#92400e">Expressing Present Wishes: I wish / If only + Past Simple</text><rect x="35" y="52" width="290" height="168" rx="12" fill="#ffffff" stroke="#dc2626" stroke-width="2"/><rect x="35" y="52" width="290" height="32" rx="12" fill="#dc2626"/><text x="180" y="73" text-anchor="middle" font-size="12" font-weight="700" fill="#ffffff">Real Present Situation (Fact)</text><text x="50" y="108" font-size="11" fill="#7f1d1d">1. I am very stressed before exams.</text><text x="50" y="138" font-size="11" fill="#7f1d1d">2. I don t have enough free time.</text><text x="50" y="168" font-size="11" fill="#7f1d1d">3. I can t concentrate in noisy rooms.</text><text x="180" y="202" text-anchor="middle" font-size="10" font-weight="700" fill="#b91c1c">Present Reality (Unwanted State)</text><rect x="375" y="52" width="295" height="168" rx="12" fill="#ffffff" stroke="#059669" stroke-width="2"/><rect x="375" y="52" width="295" height="32" rx="12" fill="#059669"/><text x="522" y="73" text-anchor="middle" font-size="12" font-weight="700" fill="#ffffff">Wish Clause (One Tense Back)</text><text x="390" y="108" font-size="11" font-weight="600" fill="#064e3b">1. I wish I weren t so stressed.</text><text x="390" y="138" font-size="11" font-weight="600" fill="#064e3b">2. If only I had more free time.</text><text x="390" y="168" font-size="11" font-weight="600" fill="#064e3b">3. I wish I could concentrate here.</text><text x="522" y="202" text-anchor="middle" font-size="10" font-weight="700" fill="#047857">I wish / If only + V2 / were / could V1</text><line x1="325" y1="136" x2="375" y2="136" stroke="#d97706" stroke-width="3"/><polygon points="375,136 367,131 367,141" fill="#d97706"/><text x="350" y="246" text-anchor="middle" font-size="11" font-weight="600" fill="#92400e">Rule: Positive fact becomes negative wish; negative fact becomes positive wish (use were for all subjects).</text></svg>', '3': '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Poppins, sans-serif"><rect width="700" height="260" rx="16" fill="#fffbeb" stroke="#d97706" stroke-width="2"/><text x="350" y="28" text-anchor="middle" font-size="15" font-weight="700" fill="#92400e">Expressing Present Wishes: I wish / If only + Past Simple</text><rect x="35" y="52" width="290" height="168" rx="12" fill="#ffffff" stroke="#dc2626" stroke-width="2"/><rect x="35" y="52" width="290" height="32" rx="12" fill="#dc2626"/><text x="180" y="73" text-anchor="middle" font-size="12" font-weight="700" fill="#ffffff">Real Present Situation (Fact)</text><text x="50" y="108" font-size="11" fill="#7f1d1d">1. I am very stressed before exams.</text><text x="50" y="138" font-size="11" fill="#7f1d1d">2. I don t have enough free time.</text><text x="50" y="168" font-size="11" fill="#7f1d1d">3. I can t concentrate in noisy rooms.</text><text x="180" y="202" text-anchor="middle" font-size="10" font-weight="700" fill="#b91c1c">Present Reality (Unwanted State)</text><rect x="375" y="52" width="295" height="168" rx="12" fill="#ffffff" stroke="#059669" stroke-width="2"/><rect x="375" y="52" width="295" height="32" rx="12" fill="#059669"/><text x="522" y="73" text-anchor="middle" font-size="12" font-weight="700" fill="#ffffff">Wish Clause (One Tense Back)</text><text x="390" y="108" font-size="11" font-weight="600" fill="#064e3b">1. I wish I weren t so stressed.</text><text x="390" y="138" font-size="11" font-weight="600" fill="#064e3b">2. If only I had more free time.</text><text x="390" y="168" font-size="11" font-weight="600" fill="#064e3b">3. I wish I could concentrate here.</text><text x="522" y="202" text-anchor="middle" font-size="10" font-weight="700" fill="#047857">I wish / If only + V2 / were / could V1</text><line x1="325" y1="136" x2="375" y2="136" stroke="#d97706" stroke-width="3"/><polygon points="375,136 367,131 367,141" fill="#d97706"/><text x="350" y="246" text-anchor="middle" font-size="11" font-weight="600" fill="#92400e">Rule: Positive fact becomes negative wish; negative fact becomes positive wish (use were for all subjects).</text></svg>', 'b4': '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Poppins, sans-serif"><rect width="700" height="260" rx="16" fill="#faf5ff" stroke="#7c3aed" stroke-width="2"/><text x="350" y="28" text-anchor="middle" font-size="15" font-weight="700" fill="#4c1d95">Wishes with WOULD vs. COULD: Annoyance and Ability</text><rect x="30" y="52" width="305" height="172" rx="12" fill="#ffffff" stroke="#7c3aed" stroke-width="2"/><rect x="30" y="52" width="305" height="34" rx="12" fill="#7c3aed"/><text x="182" y="74" text-anchor="middle" font-size="12" font-weight="700" fill="#ffffff">I wish + Someone Else + WOULD + V1</text><text x="46" y="104" font-size="11" font-weight="700" fill="#581c87">Kullanım Amacı:</text><text x="46" y="122" font-size="10" fill="#3b0764">Başka birinin rahatsız edici alışkanlığından</text><text x="46" y="138" font-size="10" fill="#3b0764">şikayet etme ve değişmesini isteme.</text><text x="46" y="162" font-size="10.5" font-weight="600" fill="#6b21a8">• I wish you wouldn t interrupt me!</text><text x="46" y="182" font-size="10.5" font-weight="600" fill="#6b21a8">• If only he would listen to my advice.</text><text x="46" y="206" font-size="10" font-weight="700" fill="#dc2626">Not: I wish I would... KULLANILMAZ!</text><rect x="365" y="52" width="305" height="172" rx="12" fill="#ffffff" stroke="#0284c7" stroke-width="2"/><rect x="365" y="52" width="305" height="34" rx="12" fill="#0284c7"/><text x="517" y="74" text-anchor="middle" font-size="12" font-weight="700" fill="#ffffff">I wish + I / We + COULD + V1</text><text x="381" y="104" font-size="11" font-weight="700" fill="#075985">Kullanım Amacı:</text><text x="381" y="122" font-size="10" fill="#0c4a6e">Kişinin kendi yeteneği, imkânı veya geleceğe</text><text x="381" y="138" font-size="10" fill="#0c4a6e">dair gerçekleştiremediği dileklerini anlatma.</text><text x="381" y="162" font-size="10.5" font-weight="600" fill="#0369a1">• I wish I could manage my anxiety better.</text><text x="381" y="182" font-size="10.5" font-weight="600" fill="#0369a1">• If only we could take a vacation soon.</text><text x="381" y="206" font-size="10" font-weight="700" fill="#059669">Özneye (I / we) bağlı imkân ve yetenek</text><text x="350" y="246" text-anchor="middle" font-size="11" font-weight="600" fill="#4c1d95">Use WOULD for other people s annoying actions; use COULD for personal ability or possibility.</text></svg>', '4': '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Poppins, sans-serif"><rect width="700" height="260" rx="16" fill="#faf5ff" stroke="#7c3aed" stroke-width="2"/><text x="350" y="28" text-anchor="middle" font-size="15" font-weight="700" fill="#4c1d95">Wishes with WOULD vs. COULD: Annoyance and Ability</text><rect x="30" y="52" width="305" height="172" rx="12" fill="#ffffff" stroke="#7c3aed" stroke-width="2"/><rect x="30" y="52" width="305" height="34" rx="12" fill="#7c3aed"/><text x="182" y="74" text-anchor="middle" font-size="12" font-weight="700" fill="#ffffff">I wish + Someone Else + WOULD + V1</text><text x="46" y="104" font-size="11" font-weight="700" fill="#581c87">Kullanım Amacı:</text><text x="46" y="122" font-size="10" fill="#3b0764">Başka birinin rahatsız edici alışkanlığından</text><text x="46" y="138" font-size="10" fill="#3b0764">şikayet etme ve değişmesini isteme.</text><text x="46" y="162" font-size="10.5" font-weight="600" fill="#6b21a8">• I wish you wouldn t interrupt me!</text><text x="46" y="182" font-size="10.5" font-weight="600" fill="#6b21a8">• If only he would listen to my advice.</text><text x="46" y="206" font-size="10" font-weight="700" fill="#dc2626">Not: I wish I would... KULLANILMAZ!</text><rect x="365" y="52" width="305" height="172" rx="12" fill="#ffffff" stroke="#0284c7" stroke-width="2"/><rect x="365" y="52" width="305" height="34" rx="12" fill="#0284c7"/><text x="517" y="74" text-anchor="middle" font-size="12" font-weight="700" fill="#ffffff">I wish + I / We + COULD + V1</text><text x="381" y="104" font-size="11" font-weight="700" fill="#075985">Kullanım Amacı:</text><text x="381" y="122" font-size="10" fill="#0c4a6e">Kişinin kendi yeteneği, imkânı veya geleceğe</text><text x="381" y="138" font-size="10" fill="#0c4a6e">dair gerçekleştiremediği dileklerini anlatma.</text><text x="381" y="162" font-size="10.5" font-weight="600" fill="#0369a1">• I wish I could manage my anxiety better.</text><text x="381" y="182" font-size="10.5" font-weight="600" fill="#0369a1">• If only we could take a vacation soon.</text><text x="381" y="206" font-size="10" font-weight="700" fill="#059669">Özneye (I / we) bağlı imkân ve yetenek</text><text x="350" y="246" text-anchor="middle" font-size="11" font-weight="600" fill="#4c1d95">Use WOULD for other people s annoying actions; use COULD for personal ability or possibility.</text></svg>', 'b5': '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Poppins, sans-serif"><rect width="700" height="260" rx="16" fill="#ecfdf5" stroke="#059669" stroke-width="2"/><text x="350" y="28" text-anchor="middle" font-size="15" font-weight="700" fill="#065f46">Empathetic Communication: Responding to Moods and Suggestions</text><rect x="28" y="52" width="205" height="170" rx="12" fill="#ffffff" stroke="#059669" stroke-width="2"/><rect x="28" y="52" width="205" height="32" rx="12" fill="#059669"/><text x="130" y="73" text-anchor="middle" font-size="11.5" font-weight="700" fill="#ffffff">1. Expressing Empathy</text><text x="42" y="104" font-size="10" fill="#064e3b">• I can see how hard this is.</text><text x="42" y="126" font-size="10" fill="#064e3b">• Put yourself in my shoes.</text><text x="42" y="148" font-size="10" fill="#064e3b">• I totally understand how</text><text x="50" y="164" font-size="10" fill="#064e3b">overwhelmed you feel.</text><text x="42" y="188" font-size="10" fill="#064e3b">• You are not alone in this.</text><rect x="248" y="52" width="205" height="170" rx="12" fill="#ffffff" stroke="#0284c7" stroke-width="2"/><rect x="248" y="52" width="205" height="32" rx="12" fill="#0284c7"/><text x="350" y="73" text-anchor="middle" font-size="11.5" font-weight="700" fill="#ffffff">2. Accepting Suggestions</text><text x="262" y="104" font-size="10" fill="#0c4a6e">• That sounds like a great idea!</text><text x="262" y="126" font-size="10" fill="#0c4a6e">• Why not? Let s give it a try.</text><text x="262" y="148" font-size="10" fill="#0c4a6e">• I hadn t thought of that.</text><text x="262" y="170" font-size="10" fill="#0c4a6e">• Thanks, I will definitely</text><text x="270" y="186" font-size="10" fill="#0c4a6e">follow your advice.</text><rect x="468" y="52" width="205" height="170" rx="12" fill="#ffffff" stroke="#d97706" stroke-width="2"/><rect x="468" y="52" width="205" height="32" rx="12" fill="#d97706"/><text x="570" y="73" text-anchor="middle" font-size="11.5" font-weight="700" fill="#ffffff">3. Politely Declining</text><text x="482" y="104" font-size="10" fill="#78350f">• I appreciate it, but I can t.</text><text x="482" y="126" font-size="10" fill="#78350f">• That s a good idea, however</text><text x="490" y="142" font-size="10" fill="#78350f">I don t feel up to it right now.</text><text x="482" y="166" font-size="10" fill="#78350f">• I d rather not, to be honest.</text><text x="482" y="188" font-size="10" fill="#78350f">• Maybe another time, thanks.</text><text x="350" y="246" text-anchor="middle" font-size="11" font-weight="600" fill="#065f46">Active listening and supportive language build trust in psychological communication.</text></svg>', '5': '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Poppins, sans-serif"><rect width="700" height="260" rx="16" fill="#ecfdf5" stroke="#059669" stroke-width="2"/><text x="350" y="28" text-anchor="middle" font-size="15" font-weight="700" fill="#065f46">Empathetic Communication: Responding to Moods and Suggestions</text><rect x="28" y="52" width="205" height="170" rx="12" fill="#ffffff" stroke="#059669" stroke-width="2"/><rect x="28" y="52" width="205" height="32" rx="12" fill="#059669"/><text x="130" y="73" text-anchor="middle" font-size="11.5" font-weight="700" fill="#ffffff">1. Expressing Empathy</text><text x="42" y="104" font-size="10" fill="#064e3b">• I can see how hard this is.</text><text x="42" y="126" font-size="10" fill="#064e3b">• Put yourself in my shoes.</text><text x="42" y="148" font-size="10" fill="#064e3b">• I totally understand how</text><text x="50" y="164" font-size="10" fill="#064e3b">overwhelmed you feel.</text><text x="42" y="188" font-size="10" fill="#064e3b">• You are not alone in this.</text><rect x="248" y="52" width="205" height="170" rx="12" fill="#ffffff" stroke="#0284c7" stroke-width="2"/><rect x="248" y="52" width="205" height="32" rx="12" fill="#0284c7"/><text x="350" y="73" text-anchor="middle" font-size="11.5" font-weight="700" fill="#ffffff">2. Accepting Suggestions</text><text x="262" y="104" font-size="10" fill="#0c4a6e">• That sounds like a great idea!</text><text x="262" y="126" font-size="10" fill="#0c4a6e">• Why not? Let s give it a try.</text><text x="262" y="148" font-size="10" fill="#0c4a6e">• I hadn t thought of that.</text><text x="262" y="170" font-size="10" fill="#0c4a6e">• Thanks, I will definitely</text><text x="270" y="186" font-size="10" fill="#0c4a6e">follow your advice.</text><rect x="468" y="52" width="205" height="170" rx="12" fill="#ffffff" stroke="#d97706" stroke-width="2"/><rect x="468" y="52" width="205" height="32" rx="12" fill="#d97706"/><text x="570" y="73" text-anchor="middle" font-size="11.5" font-weight="700" fill="#ffffff">3. Politely Declining</text><text x="482" y="104" font-size="10" fill="#78350f">• I appreciate it, but I can t.</text><text x="482" y="126" font-size="10" fill="#78350f">• That s a good idea, however</text><text x="490" y="142" font-size="10" fill="#78350f">I don t feel up to it right now.</text><text x="482" y="166" font-size="10" fill="#78350f">• I d rather not, to be honest.</text><text x="482" y="188" font-size="10" fill="#78350f">• Maybe another time, thanks.</text><text x="350" y="246" text-anchor="middle" font-size="11" font-weight="600" fill="#065f46">Active listening and supportive language build trust in psychological communication.</text></svg>', 'b6': '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Poppins, sans-serif"><rect width="700" height="260" rx="16" fill="#f8fafc" stroke="#475569" stroke-width="2"/><text x="350" y="28" text-anchor="middle" font-size="15" font-weight="700" fill="#0f172a">Theme 5 Summary: Moods, Suggestions and Wishes at a Glance</text><rect x="22" y="54" width="210" height="168" rx="10" fill="#dbeafe" stroke="#2563eb" stroke-width="2"/><text x="127" y="76" text-anchor="middle" font-size="12" font-weight="700" fill="#1e40af">1. Mood Idioms &amp; Words</text><text x="36" y="102" font-size="10" fill="#1e3a8a">• On cloud nine (Very happy)</text><text x="36" y="122" font-size="10" fill="#1e3a8a">• Feel blue / Down in the dumps</text><text x="36" y="142" font-size="10" fill="#1e3a8a">• Over the moon (Delighted)</text><text x="36" y="162" font-size="10" fill="#1e3a8a">• On edge (Nervous, tense)</text><text x="36" y="182" font-size="10" fill="#1e3a8a">• Keep one s chin up (Stay brave)</text><text x="36" y="202" font-size="10" fill="#1e3a8a">• Mixed feelings (Uncertain)</text><rect x="245" y="54" width="210" height="168" rx="10" fill="#dcfce7" stroke="#16a34a" stroke-width="2"/><text x="350" y="76" text-anchor="middle" font-size="12" font-weight="700" fill="#166534">2. Making Suggestions</text><text x="259" y="102" font-size="10" fill="#14532d">• Why don t you + V1?</text><text x="259" y="122" font-size="10" fill="#14532d">• Shall we / Let s + V1</text><text x="259" y="142" font-size="10" fill="#14532d">• How / What about + V-ing?</text><text x="259" y="162" font-size="10" fill="#14532d">• You should / had better + V1</text><text x="259" y="182" font-size="10" fill="#14532d">• I suggest (that) you + V1</text><text x="259" y="202" font-size="10" fill="#14532d">• If I were you, I would + V1</text><rect x="468" y="54" width="210" height="168" rx="10" fill="#fef3c7" stroke="#d97706" stroke-width="2"/><text x="573" y="76" text-anchor="middle" font-size="12" font-weight="700" fill="#92400e">3. Expressing Wishes</text><text x="482" y="102" font-size="10" fill="#78350f">• Present State: wish + V2 / were</text><text x="488" y="118" font-size="9.5" fill="#92400e">(I wish I were calmer now)</text><text x="482" y="142" font-size="10" fill="#78350f">• Ability: wish + could + V1</text><text x="488" y="158" font-size="9.5" fill="#92400e">(I wish I could sleep well)</text><text x="482" y="182" font-size="10" fill="#78350f">• Complaint: wish + would + V1</text><text x="488" y="198" font-size="9.5" fill="#92400e">(I wish you would stop yelling)</text><text x="350" y="244" text-anchor="middle" font-size="11" font-weight="600" fill="#334155">Mastering these structures enables fluent expression of feelings, advice and wishes.</text></svg>', '6': '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Poppins, sans-serif"><rect width="700" height="260" rx="16" fill="#f8fafc" stroke="#475569" stroke-width="2"/><text x="350" y="28" text-anchor="middle" font-size="15" font-weight="700" fill="#0f172a">Theme 5 Summary: Moods, Suggestions and Wishes at a Glance</text><rect x="22" y="54" width="210" height="168" rx="10" fill="#dbeafe" stroke="#2563eb" stroke-width="2"/><text x="127" y="76" text-anchor="middle" font-size="12" font-weight="700" fill="#1e40af">1. Mood Idioms &amp; Words</text><text x="36" y="102" font-size="10" fill="#1e3a8a">• On cloud nine (Very happy)</text><text x="36" y="122" font-size="10" fill="#1e3a8a">• Feel blue / Down in the dumps</text><text x="36" y="142" font-size="10" fill="#1e3a8a">• Over the moon (Delighted)</text><text x="36" y="162" font-size="10" fill="#1e3a8a">• On edge (Nervous, tense)</text><text x="36" y="182" font-size="10" fill="#1e3a8a">• Keep one s chin up (Stay brave)</text><text x="36" y="202" font-size="10" fill="#1e3a8a">• Mixed feelings (Uncertain)</text><rect x="245" y="54" width="210" height="168" rx="10" fill="#dcfce7" stroke="#16a34a" stroke-width="2"/><text x="350" y="76" text-anchor="middle" font-size="12" font-weight="700" fill="#166534">2. Making Suggestions</text><text x="259" y="102" font-size="10" fill="#14532d">• Why don t you + V1?</text><text x="259" y="122" font-size="10" fill="#14532d">• Shall we / Let s + V1</text><text x="259" y="142" font-size="10" fill="#14532d">• How / What about + V-ing?</text><text x="259" y="162" font-size="10" fill="#14532d">• You should / had better + V1</text><text x="259" y="182" font-size="10" fill="#14532d">• I suggest (that) you + V1</text><text x="259" y="202" font-size="10" fill="#14532d">• If I were you, I would + V1</text><rect x="468" y="54" width="210" height="168" rx="10" fill="#fef3c7" stroke="#d97706" stroke-width="2"/><text x="573" y="76" text-anchor="middle" font-size="12" font-weight="700" fill="#92400e">3. Expressing Wishes</text><text x="482" y="102" font-size="10" fill="#78350f">• Present State: wish + V2 / were</text><text x="488" y="118" font-size="9.5" fill="#92400e">(I wish I were calmer now)</text><text x="482" y="142" font-size="10" fill="#78350f">• Ability: wish + could + V1</text><text x="488" y="158" font-size="9.5" fill="#92400e">(I wish I could sleep well)</text><text x="482" y="182" font-size="10" fill="#78350f">• Complaint: wish + would + V1</text><text x="488" y="198" font-size="9.5" fill="#92400e">(I wish you would stop yelling)</text><text x="350" y="244" text-anchor="middle" font-size="11" font-weight="600" fill="#334155">Mastering these structures enables fluent expression of feelings, advice and wishes.</text></svg>'}

def uygula(v):
    for idx, b in enumerate(v.get('bolumler', []), 1):
        svg = GORSELLER.get(f'b{idx}') or GORSELLER.get(str(idx))
        if svg:
            b['gorsel'] = svg
    return v
